const bytes=value=>numeric(value)===null?'—':`${number(Number(value)/1024**3)} GiB`;
const when=value=>{const date=new Date(value);return value&&Number.isFinite(date.getTime())?formatUI(value,(locale,value)=>formatPanelDate(value,locale,{dateStyle:'medium',timeStyle:'short'})):nodeText('Not observed yet','Chưa ghi nhận');};
const button=(label,action,id='',kind='',glyph='')=>`<button type="button" class="btn ${kind}" data-intent="${buttonIntent(action,{primary:kind==='primary',danger:kind.includes('danger')})}" data-action="${action}"${id?` data-node-id="${escape(id)}"`:''}>${glyph?`<svg class="icon" aria-hidden="true"><use href="#i-${glyph}"/></svg>`:''}${escape(label)}</button>`;
